package com.ke.ticketsystemke.dto;import com.ke.ticketsystemke.entity.*;import java.time.Instant;
public record WarrantyAttachmentResponse(Long id,WarrantyAttachmentCategory category,Long replacementId,String displayFilename,String detectedMimeType,long sizeBytes,Integer imageWidth,Integer imageHeight,boolean active,Long supersededByAttachmentId,Instant uploadedAt,String uploadedByEmployeeId,String uploadedByEmployeeName,Instant deactivatedAt,String deactivationReason,boolean previewAvailable,Long version,String contentPath){public static WarrantyAttachmentResponse from(WarrantyAttachment a){Long claim=a.getWarrantyClaim().getId();Long ticket=a.getWarrantyClaim().getTicket().getId();return new WarrantyAttachmentResponse(a.getId(),a.getCategory(),a.getWarrantyReplacement()==null?null:a.getWarrantyReplacement().getId(),a.getDisplayFilename(),a.getDetectedMimeType(),a.getSizeBytes(),a.getImageWidth(),a.getImageHeight(),a.isActive(),a.getSupersededByAttachmentId(),a.getUploadedAt(),a.getUploadedByEmployeeId(),a.getUploadedByEmployeeName(),a.getDeactivatedAt(),a.getDeactivationReason(),true,a.getVersion(),"/volt/tickets/"+ticket+"/warranty/"+claim+"/attachments/"+a.getId()+"/content");}}
